def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    if n < 10:
        if history[-1][1] == 'D':
            return 'D'
        return 'C'

    if n == 10:
        total_opp_d = sum(1 for a, b in history if b == 'D')
        if total_opp_d == 0:
            return 'D'
        else:
            if history[-1][1] == 'D':
                return 'D'
            return 'C'

    if n == 11:
        if history[10][0] == 'D':
            return 'C'
        else:
            if history[-1][1] == 'D':
                return 'D'
            return 'C'

    total_opp_d = sum(1 for a, b in history if b == 'D')
    recent5 = history[-5:]
    opp_d5 = sum(1 for a, b in recent5 if b == 'D')

    if total_opp_d == 0:
        if n % 5 == 0:
            return 'D'
        return 'C'

    if opp_d5 >= 3:
        return 'D'

    if history[-1][1] == 'D':
        return 'C'

    return 'C'
